def truncate_utf8(text, byte_limit):
    if byte_limit == 0:
        return ''
    encoded_text = text.encode('utf-8')
    if len(encoded_text) <= byte_limit:
        return text
    for i in range(byte_limit, -1, -1):
        if encoded_text[i] & 0xC0 != 0x80:
            return text[:i]
    return text[:byte_limit]
